from pathlib import Path
import pandas as pd,numpy as np,matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
out=Path('outputs/full_followup_recovery_20261101');p=pd.read_csv(out/'pooled.csv');e=pd.read_csv(out/'effects.csv');raw=pd.read_csv('outputs/researcher_scope_20261101/annual_input.csv')
labels={'M. pyrifera':'Kelp','S. pulcher':'Sheephead','P. interruptus':'Lobster','M. franciscanus':'Red urchin','S. purpuratus':'Purple urchin'}
order=[('M. pyrifera','Bio'),('S. pulcher','Bio'),('S. pulcher','Den'),('P. interruptus','Bio'),('P. interruptus','Den'),('M. franciscanus','Bio'),('M. franciscanus','Den'),('S. purpuratus','Bio'),('S. purpuratus','Den')]
def label(tx,r):return labels[tx]+(' biomass' if r=='Bio' else ' density')
def get(sc,mt,tx,r):
 x=p[(p.scenario==sc)&(p.metric==mt)&(p.Taxa==tx)&(p.Resp==r)];return None if x.empty else x.iloc[0]
def show(x,slope=False):
 if x is None:return 'Unavailable'
 f=lambda v:100*np.expm1(v) if slope else v
 ans=f'{f(x.estimate):+.1f}%' if slope else f'{x.estimate:.3f}'
 if np.isfinite(x.low):ans+=f' [{f(x.low):.1f}, {f(x.high):.1f}]; q={x.q:.3f}' if slope else f' [{x.low:.3f}, {x.high:.3f}]; q={x.q:.3f}'
 else:ans+='; no reliable pooled interval'
 return ans
for metric,name in [('Post_slope','recovery_rates'),('Change','before_after_changes')]:
 fig,ax=plt.subplots(figsize=(11,7.7));fig.subplots_adjust(left=.25,right=.98,top=.97,bottom=.12)
 for j,(tx,r) in enumerate(order):
  for sc,offset,color in [('Nine_year_matched',-.22,'#777777'),('Full_matched',0,'#286785'),('Full',.22,'#C05B2C')]:
   x=get(sc,metric,tx,r)
   if x is None:continue
   f=lambda v:100*np.expm1(v) if metric=='Post_slope' else v
   if np.isfinite(x.low):ax.plot([f(x.low),f(x.high)],[j+offset]*2,color=color,lw=1.4)
   ax.plot(f(x.estimate),j+offset,'o',ms=5,color=color,mfc=color if np.isfinite(x.low) else 'white')
 ax.set_yticks(range(len(order)));ax.set_yticklabels([label(*pair) for pair in order],color='black');ax.tick_params(axis='y',labelleft=True);ax.invert_yaxis();ax.axvline(0,color='.6',ls='--',lw=.8);ax.grid(axis='x',alpha=.15);ax.spines[['top','right']].set_visible(False)
 ax.set_xlabel('Annual change in protected/reference ratio (%)' if metric=='Post_slope' else 'Before–after change in log protected/reference ratio')
 fig.savefig(out/(name+'.png'),dpi=180,bbox_inches='tight');fig.savefig(out/(name+'.pdf'));plt.close(fig)
# Newly eligible short late Point Dume histories, without extrapolation.
fig,axs=plt.subplots(1,3,figsize=(10.5,3.8));fig.subplots_adjust(left=.09,right=.98,bottom=.2,top=.97,wspace=.4)
for ax,tx in zip(axs,['M. franciscanus','S. purpuratus','P. interruptus']):
 x=raw[(raw.MPA=='Point Dume SMCA')&(raw.Source=='PISCO')&(raw.Resp=='Den')&(raw.Taxa==tx)&(raw.t>0)].sort_values('year')
 ax.plot(x.year,np.exp(x.lnDiff),'o-',color='#286785');ax.set_yscale('log');ax.set_xticks(x.year);ax.set_ylabel(labels[tx]+' ratio');ax.set_xlabel('Survey year');ax.axhline(1,color='.7',ls='--');ax.spines[['top','right']].set_visible(False)
fig.savefig(out/'point_dume_late_records.png',dpi=180);fig.savefig(out/'point_dume_late_records.pdf');plt.close(fig)
lines=['# Full-follow-up recovery analysis','', 'November 1, 2026. Review only. The manuscript, supplement, canonical results and source data were not updated. Researcher/ecological exclusions are unchanged; no baseline-trend or result-direction selection was used.','', '## What changed','', 'All actual post-designation survey years are included. Designation years remain omitted consistently, and only strictly prior observations define Before. Full follow-up supports55 before–after histories and169 post-protection slopes, compared with54 and162 in the first-nine-year analysis. Slopes describe annual change in protected/reference ratios, not absolute population recovery. No projected years were inserted.','', 'The same-history comparison is essential: restoring later years strengthens several kelp/urchin patterns. Expanding the roster to all histories that now satisfy the same three-survey-year minimum separately adds seven histories, including short late Point Dume records; these change the pooled urchin density results. This does not justify selecting or excluding them by direction.','', '## Post-protection trajectories','', 'Entries are annual percentage change in the protected/reference ratio, with95%CR2 intervals and BH q across nine response slots. Zero denotes no trend. Gray/blue comparisons use identical histories. The final column adds all newly eligible histories. Linear slopes summarize the observed trajectory; they do not establish constant recovery rates or a causal effect of designation.','', '| Response | Years1–9, matched histories | All years, same histories | All years, expanded roster |','|---|---|---|---|']
for tx,r in order:lines.append('| '+label(tx,r)+' | '+' | '.join(show(get(s,'Post_slope',tx,r),True) for s in ['Nine_year_matched','Full_matched','Full'])+' |')
lines+=['','Kelp and purple-urchin biomass retain the same directions and similar estimates after roster expansion, but their full-roster adjusted q values are both0.078. Their unadjusted intervals exclude zero. The matched-roster adjusted results differ partly because BH uses the entire nine-response family; a change in q alone does not mean the focal estimate changed. Lobster density increases on average, but the full-follow-up interval includes zero. Sheephead post slopes do not show a clear increase; a high protected/reference level is distinct from a continuing increase.','', '## Before–after changes','', 'These compare the average post-protection ratio with its pre-protection baseline. They are separate from post slopes and are not pooled together. Entries are log changes, with95%CR2 intervals and BH q.','', '| Response | Years1–9, matched histories | All years, same histories | All years, expanded roster |','|---|---|---|---|']
for tx,r in order:lines.append('| '+label(tx,r)+' | '+' | '.join(show(get(s,'Change',tx,r)) for s in ['Nine_year_matched','Full_matched','Full'])+' |')
lines+=['','Kelp before–after change strengthens from0.341 to0.659 log units when later years are restored (roughly a1.93-fold change in the protected/reference ratio; unadjusted95%interval1.17–3.18; q=0.122). Purple-urchin density remains negative but uncertain. Sparse independent replication prevents reliable pooled intervals for several biomass responses and lobster density. No qualifying lobster-biomass baseline comparison is available.','', '## New full-follow-up histories','', '| History | Post survey years | Why now eligible |','|---|---|---|']
a=set(e[(e.scenario=='Nine_year')&(e.metric=='Post_slope')].series_id);b=e[(e.scenario=='Full')&(e.metric=='Post_slope')];added=b[~b.series_id.isin(a)]
added.to_csv(out/'newly_eligible_histories.csv',index=False)
for _,r in added.iterrows():
 reason='First-nine-year series was constant; later observations provide estimable variance' if r.MPA=='Harris Point SMR' else 'At least three observations become available when later years are retained'
 lines.append(f'| {r.MPA}, {r.Source}, {label(r.Taxa,r.Resp)} | {r.after_years} | {reason} |')
lines+=['','Point Dume SMCA red- and purple-urchin density histories cover only2021–2023 (protection ages9–11), not the entire eleven-year period. Their log slopes are+0.662 and+2.254 per year, respectively. Those sharp local changes pull the full pooled density estimates upward and increase heterogeneity. The three-year threshold was retained consistently; these short trajectories should not be presented as eleven-year recovery estimates. The figure shows the actual observed ratios without extrapolation.','', '## Baseline support and assumption sensitivity','', 'The55 baseline-supported and114 no-qualifying-baseline slope histories are disjoint and sum to169. The all-history slopes are an overview; the groups are also exported separately. In the no-qualifying-baseline group, kelp rises (q=.025) and purple-urchin biomass declines (q=.029). These are post-protection associations without a qualifying baseline, not evidence that designation caused them. Baseline-supported slope comparisons remain uncertain. Do not select the group with favorable significance as the paper’s main result.','', 'Segmented linear baseline sensitivities are in pooled.csv: Slope_change compares After and Before slopes; Trend_adjusted_change compares observed After values with an extrapolated linear Before trajectory. Neither resolves broad causal attribution. Kelp full-follow-up change falls from0.659 under the flat baseline to0.176 [−0.631,0.983] after baseline-trend adjustment. Baseline limitations remain despite longer follow-up.','', 'HAC lags1,3 and5 are all exported. Kelp and purple-urchin biomass directions persist, with full-roster adjusted q about0.057–0.095. Purple-urchin density is sensitive to these covariance choices: the lag1 estimate is−0.100 log units/year, versus−0.003 at lag3. The leave-one-MPA check recovers the matched-roster red/purple density slopes when Point Dume SMCA is omitted; this diagnoses influence, not a justification for excluding it. Separate-program checks show that kelp growth and purple-urchin biomass decline are clearest in PISCO; the satellite kelp slope interval includes zero. These are conditional uncertainty checks; conversion/size uncertainty and sampling comparability are not resolved by them.','', '## Checks and interpretation limits','', 'Nine-year and full-period before–after estimates reproduce the earlier researcher-scope runs. Independent Python reconstruction checks every individual effect/HAC covariance, pooled GLS point estimates, interval arithmetic and BH adjustment. Matched histories are identical between windows; baseline-supported and no-baseline groups do not overlap. The487 protected artifacts remain unchanged. See verification.json.','', 'Linear_diagnostics.csv records residual degrees of freedom and maximum Cook distance. Leave_one_MPA.csv reports influence of each MPA on full-period pooled estimates; program_slopes.csv separates survey programs. These are descriptive diagnostics without additional BH claims. Linear slopes are deliberately simple time summaries, not a demonstrated best nonlinear recovery model. Annual sampling and baseline differences still limit interpretation, and histories with only three years have especially weak support for trajectory shape.','', '## Figures','', '- recovery_rates.png/pdf: pooled annual percentage changes. Upper gray points use years1–9; middle blue points use all observed years on the same histories; lower orange points use all full-follow-up eligible histories. Bars are95%CR2 intervals. Open points have insufficient independent information for reliable pooled intervals.','- before_after_changes.png/pdf: same colors and ordering, but the horizontal axis is Before–After change in the log protected/reference ratio. Zero is no change.','- point_dume_late_records.png/pdf: observed PISCO protected/reference density ratios for red urchins, purple urchins and lobsters at Point Dume SMCA,2021–2023. Logarithmic vertical axes; no extrapolation or fitted uncertainty bands. These ratios retain the source zero adjustment.','', '## Reproduction','', '```sh','Rscript code/tools/refit_full_followup_recovery.R','Rscript code/tools/check_recovery_influence.R','python3 code/tools/check_full_followup_recovery.py','python3 code/tools/report_full_followup_recovery.py','```','', 'The analysis shows that longer follow-up can reveal patterns obscured by a nine-year window, but it does not restore every old finding. Membership, follow-up length, baseline support and the precise recovery question all remain consequential. No manuscript changes have been made.']
(out/'README.md').write_text('\n'.join(lines)+'\n');print('Report and figures saved')
